glossary <- tibble(term = c("AIC", "Adjusted R-squared", "Adjusted Rand index", "Bartlett's test", "Baseline", "BIC", "Biplot", "Bootstrap", "Boundary rate", "Breusch-Pagan", "Burn-in", "Candidate pool", "Cluster", "Cold start", "Collinearity", "Communality", "Confidence interval", "Cook's distance", "Curtailed innings", "Death overs", "DFBETAS", "DFFITS", "Eigenvalue", "Factor", "Factor loading", "Factor score", "Gap statistic", "Goldfeld-Quandt", "HC3", "Heteroscedasticity", "Identifiability", "Interaction", "K-means", "Kaiser rule", "KMO", "Leakage", "Leverage", "MAE", "Mahalanobis distance", "Maximum likelihood", "Oblimin", "OLS", "Outlier", "Parallel analysis", "PCA", "PCR", "Polynomial term", "Prediction interval", "Predictive R-squared", "Residual", "Residual standard error", "RMSE", "Robust regression", "Rolling origin", "Season split", "Shrinkage", "Silhouette", "Smearing", "Standardisation", "Studentized residual", "Uniqueness", "Validation", "Varimax", "VIF", "Ward.D2", "White test", "WLS"),
 definition = c("Fit-versus-complexity criterion using a parameter penalty.", "Training fit adjusted for model size.", "Chance-adjusted similarity of two cluster partitions.", "Test of whether a correlation matrix is identity.", "Simple reference prediction rule.", "Fit-versus-complexity criterion with sample-size-dependent penalty.", "Plot of component scores and feature loading directions.", "Repeated resampling to estimate uncertainty.", "Fraction of deliveries or faced balls that are actual boundaries, as specified.", "Test linking squared residual variation with predictors.", "Initial history excluded from modelling to support later features.", "All proposed predictors before selection.", "Group of similar feature profiles.", "Little or no historical information.", "Predictors that overlap strongly in their information.", "Fraction of feature variance represented by common factors.", "Range describing uncertainty about a mean relationship or parameter.", "Summary of an observation's effect on the fitted model.", "Fewer scheduled legal balls without being all out.", "Final scheduled overs used for late-innings bowling rates.", "Coefficient change after removing a case, standardised by uncertainty.", "Standardised prediction change after removing a case.", "Variance along a component direction.", "Latent source of shared measurement variation.", "Relationship between a measurement and a latent factor.", "Estimated location of an observation along latent factors.", "Clustering separation compared with random reference profiles.", "Variance comparison between ordered subsets.", "Leverage-adjusted robust coefficient covariance estimator.", "Conditional error variance differs among observations.", "Parameters can be uniquely estimated under the model's constraints.", "Effect of one predictor depends on another.", "Clustering by minimising squared distances to group centres.", "Retain standardised components with eigenvalues above unity; used here only as a reference.